 "content": "def transform(grid):
    """Combine aligned 3x6 color layers using priority 5 > 4 > 8 > 2."""
    if len(grid) != 12 or any(len(row) != 6 for row in grid):
        raise ValueError("expected a 12x6 input")
    priority = (5, 4, 8, 2)
    out = [[0 for _ in range(6)] for _ in range(3)]
    for r in range(3):
        for c in range(6):
            present = {grid[layer * 3 + r][c] for layer in range(4)}
            out[r][c] = next((color for color in priority if color in present), 0)
    return out
